"use strict";

(function () {
    window.initAdminSelect2 = function (container) {
        var $root = container ? $(container) : $(document);
        var scopedInit = Boolean(container);

        $root
        .find("select")
            .not(".select2, .select2-hide-search, .sort-option-modal")
            .each(function () {
            var $select = $(this);

            if ($select.hasClass("select2-hidden-accessible")) {
                return;
            }

            if ($select.hasClass("d-none") || $select.hasClass("display-none")) {
                return;
            }

            if (!scopedInit && !$select.is(":visible")) {
                return;
            }

            var options = {
                width: "100%",
                minimumResultsForSearch: Infinity,
            };
            var $dropdownParent = $select.closest(
                ".select-dropdown-section, .modal-content, .modal"
            );

            if ($dropdownParent.length) {
                options.dropdownParent = $dropdownParent.first();
                options.dropdownCssClass = "admin-select2-dropdown";
            }

            $select.select2(options);
        });
    };

    $(document).ready(function () {
        initAdminSelect2();
    });

    $(document).on("shown.bs.tab", 'a[data-bs-toggle="tab"]', function (e) {
        var target = $(e.target).attr("href");

        if (target && target.charAt(0) === "#") {
            initAdminSelect2($(target));
        }
    });

    $(document).on("shown.bs.collapse", function (e) {
        initAdminSelect2($(e.target));
    });

    $(document).on("shown.bs.modal", ".modal", function () {
        initAdminSelect2($(this));
    });

    var storageKey = "mv_mobile_header_hidden";
    var cycleKey = "mv_mobile_header_hide_cycle";

    function applyCollapsedTheme() {
        var cycle = parseInt(localStorage.getItem(cycleKey) || "0", 10);
        if (cycle > 0 && cycle % 2 === 0) {
            document.body.classList.add("mobile-header-theme-dark");
        } else {
            document.body.classList.remove("mobile-header-theme-dark");
        }
    }

    function applyStoredState() {
        if (window.innerWidth > 991.98) {
            return;
        }
        if (localStorage.getItem(storageKey) === "1") {
            document.body.classList.add("mobile-header-collapsed");
            applyCollapsedTheme();
        }
    }

    function showHeaderPanel() {
        document.body.classList.remove("mobile-header-collapsed");
        document.body.classList.remove("mobile-header-theme-dark");
        localStorage.setItem(storageKey, "0");
    }

    function hideHeaderPanel() {
        if (window.innerWidth > 991.98) {
            return;
        }
        var cycle = parseInt(localStorage.getItem(cycleKey) || "0", 10) + 1;
        localStorage.setItem(cycleKey, String(cycle));
        document.body.classList.add("mobile-header-collapsed");
        applyCollapsedTheme();
        localStorage.setItem(storageKey, "1");
        $(".pcoded-header .navbar-collapse").slideUp(120);
    }

    function collapseHeaderAfterAction() {
        if (
            window.innerWidth <= 991.98 &&
            !document.body.classList.contains("mobile-header-collapsed")
        ) {
            hideHeaderPanel();
        }
    }

    function shouldIgnoreOutsideHeaderClick(target) {
        return $(target).closest(
            ".pcoded-header .navbar-collapse, #mobile-header, #mobile-collapse1, .pcoded-header .dropdown-menu, .pcoded-header .dropdown-toggle"
        ).length > 0;
    }

    $(function () {
        applyStoredState();

        $(document).on("click", "#mobile-header-hide-btn", function (event) {
            event.preventDefault();
            hideHeaderPanel();
        });

        $(document).on("click", "#mobile-sidebar-toggle-btn", function (event) {
            event.preventDefault();
            $("#mobile-collapse1").trigger("click");
            collapseHeaderAfterAction();
        });

        $(document).on(
            "click",
            '.pcoded-header .navbar-collapse .nav-menu a:not([data-bs-toggle="dropdown"]), .pcoded-header .navbar-collapse .nav-menu .dropdown-menu a, .pcoded-header .navbar-collapse .lang, .pcoded-header .navbar-collapse .profile-notification .dropdown-item, .pcoded-header .navbar-collapse .notification .noti-footer a, .pcoded-header .navbar-collapse .notification .noti-head a',
            function () {
                collapseHeaderAfterAction();
            }
        );

        $(document).on("click", "#mobile-header", function () {
            if (document.body.classList.contains("mobile-header-collapsed")) {
                showHeaderPanel();
                $(".pcoded-header .navbar-collapse").slideDown(120);
            }
        });

        $(document).on("click", function (event) {
            if (
                window.innerWidth <= 991.98 &&
                !document.body.classList.contains("mobile-header-collapsed") &&
                !shouldIgnoreOutsideHeaderClick(event.target)
            ) {
                hideHeaderPanel();
            }
        });
    });

    window.addEventListener("resize", function () {
        if (window.innerWidth <= 991.98) {
            applyStoredState();
        }
    });
})();
